use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use tokio::sync::mpsc;
use serde::{Deserialize, Serialize};
use sha2::{Sha256, Digest};
use hmac::{Hmac, Mac};

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct WsSession {
    pub session_id: String,
    pub node_id: String,
    pub origin: String,
    pub authenticated: bool,
    pub nonce: u64,
    pub permissions: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ContractCall {
    pub method: String,
    pub params: Vec<String>,
    pub caller_session: String,
    pub timestamp: u64,
}

pub struct WebSocketBridge {
    sessions: Arc<RwLock<HashMap<String, WsSession>>>,
    contract_state: Arc<RwLock<HashMap<String, u64>>>,
    hmac_key: Vec<u8>,
    allowed_origins: Vec<String>,
    nonce_window: u64,
}

impl WebSocketBridge {
    pub fn new(hmac_key: Vec<u8>, allowed_origins: Vec<String>) -> Self {
        WebSocketBridge {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            contract_state: Arc::new(RwLock::new(HashMap::new())),
            hmac_key,
            allowed_origins,
            nonce_window: 300,
        }
    }

    pub fn validate_origin(&self, origin: &str) -> bool {
        self.allowed_origins.iter().any(|allowed| {
            origin == allowed || origin.ends_with(&format!(".{}", allowed))
        })
    }

    pub fn create_session(&self, node_id: &str, origin: &str) -> Option<WsSession> {
        if !self.validate_origin(origin) {
            return None;
        }
        let session_id = self.generate_session_id(node_id, origin);
        let session = WsSession {
            session_id: session_id.clone(),
            node_id: node_id.to_string(),
            origin: origin.to_string(),
            authenticated: false,
            nonce: 0,
            permissions: vec![],
        };
        let mut sessions = self.sessions.write().unwrap();
        sessions.insert(session_id, session.clone());
        Some(session)
    }

    fn generate_session_id(&self, node_id: &str, origin: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(node_id.as_bytes());
        hasher.update(origin.as_bytes());
        hasher.update(&self.hmac_key);
        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        hasher.update(&timestamp.to_le_bytes());
        format!("{:x}", hasher.finalize())
    }

    pub fn authenticate_session(
        &self,
        session_id: &str,
        challenge_response: &[u8],
        nonce: u64,
    ) -> bool {
        let sessions = self.sessions.read().unwrap();
        let session = match sessions.get(session_id) {
            Some(s) => s,
            None => return false,
        };

        // Replay protection: reject nonces that are not strictly greater
        // than the last accepted nonce for this session.
        if nonce <= session.nonce {
            return false;
        }

        let mut mac = HmacSha256::new_from_slice(&self.hmac_key).unwrap();
        mac.update(session_id.as_bytes());
        mac.update(&nonce.to_le_bytes());

        // Constant-time verification
        if mac.verify_slice(challenge_response).is_err() {
            return false;
        }

        drop(sessions);
        let mut sessions = self.sessions.write().unwrap();
        if let Some(s) = sessions.get_mut(session_id) {
            // Re-check monotonicity under the write lock to avoid races.
            if nonce <= s.nonce {
                return false;
            }
            s.authenticated = true;
            s.nonce = nonce;
            s.permissions = vec!["read".to_string(), "write".to_string()];
            true
        } else {
            false
        }
    }

    pub fn validate_contract_call(&self, call: &ContractCall) -> bool {
        let sessions = self.sessions.read().unwrap();
        let session = match sessions.get(&call.caller_session) {
            Some(s) => s,
            None => return false,
        };

        if !session.authenticated {
            return false;
        }

        // Nonce replay protection - check window
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        if call.timestamp + self.nonce_window < current_time {
            return false;
        }

        true
    }

    pub fn execute_contract_call(&self, call: &ContractCall) -> Result<String, String> {
        // Atomic validation and execution under single lock scope
        let sessions = self.sessions.read().unwrap();
        let session = match sessions.get(&call.caller_session) {
            Some(s) => s,
            None => return Err("Session not found".to_string()),
        };

        if !session.authenticated {
            return Err("Unauthorized contract call".to_string());
        }

        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        if call.timestamp + self.nonce_window < current_time {
            return Err("Call expired".to_string());
        }

        match call.method.as_str() {
            "transfer" => {
                if !session.permissions.contains(&"write".to_string()) {
                    return Err("No write permission".to_string());
                }
                self.execute_transfer(&call.params, &session.node_id)
            }
            "balance" => {
                if !session.permissions.contains(&"read".to_string()) {
                    return Err("No read permission".to_string());
                }
                self.get_balance(&call.params)
            }
            _ => Err("Unknown method".to_string()),
        }
    }

    fn execute_transfer(&self, params: &[String], caller: &str) -> Result<String, String> {
        if params.len() != 2 {
            return Err("Transfer requires [to, amount]".to_string());
        }
        let to = &params[0];
        let amount: u64 = params[1].parse().map_err(|_| "Invalid amount")?;

        let mut state = self.contract_state.write().unwrap();
        let caller_balance = state.entry(caller.to_string()).or_insert(1000);
        if *caller_balance < amount {
            return Err("Insufficient balance".to_string());
        }
        *caller_balance -= amount;
        let to_balance = state.entry(to.clone()).or_insert(0);
        *to_balance += amount;

        Ok(format!("Transferred {} to {}", amount, to))
    }

    fn get_balance(&self, params: &[String]) -> Result<String, String> {
        if params.is_empty() {
            return Err("Balance requires [account]".to_string());
        }
        let state = self.contract_state.read().unwrap();
        let balance = state.get(&params[0]).unwrap_or(&0);
        Ok(format!("{}", balance))
    }

    pub fn handle_k8s_health_probe(&self, probe_origin: &str) -> bool {
        // Only exact match for k8s internal service DNS
        probe_origin == "kubernetes.default.svc.cluster.local"
    }

    pub fn upgrade_connection(
        &self,
        origin: &str,
        node_id: &str,
        is_health_probe: bool,
    ) -> Result<WsSession, String> {
        let origin_valid = if is_health_probe {
            self.handle_k8s_health_probe(origin)
        } else {
            self.validate_origin(origin)
        };

        if !origin_valid {
            return Err("Origin not allowed".to_string());
        }

        self.create_session(node_id, origin)
            .ok_or_else(|| "Session creation failed".to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_origin() {
        let bridge = WebSocketBridge::new(
            b"secret_key_for_testing".to_vec(),
            vec!["blockchain.internal".to_string()],
        );
        assert!(bridge.validate_origin("node1.blockchain.internal"));
        assert!(!bridge.validate_origin("evil.com"));
        assert!(!bridge.validate_origin("evilblockchain.internal"));
    }

    #[test]
    fn test_session_lifecycle() {
        let bridge = WebSocketBridge::new(
            b"secret_key_for_testing".to_vec(),
            vec!["blockchain.internal".to_string()],
        );
        let session = bridge.create_session("node1", "node1.blockchain.internal");
        assert!(session.is_some());
    }
}
